/****************************************************************************
 * Contest 2026 team 123 board - boot initialization
 ****************************************************************************/

#include <nuttx/board.h>
#include <sys/mount.h>
#include <stdio.h>

void openvela_board_initialize(void)
{
  /* Mount procfs so networking tools like ifconfig can read /proc/net */
  int ret = mount(NULL, "/proc", "procfs", 0, NULL);
  if (ret < 0)
    {
      printf("board_boot: failed to mount procfs: %d\n", ret);
    }
}
